const nomeCompleto = body.nome_completo || '';
const email = body.email || '';
const telefone = (body.telefone || '').replace(/\D/g, '');
const cpfCnpj = body.cpf_cnpj || '';

const nomeNegocio = body.nome_negocio || '';
const tipoNegocio = body.tipo_negocio || 'salao_beleza';
const endereco = body.endereco || '';
const cidadeEstado = body.cidade_estado || '';
const instagram = body.instagram || '';
const horarioFuncionamento = body.horario_funcionamento || '';
const formasPagamento = body.formas_pagamento || '';

const nomeAtendente = body.nome_atendente || 'Atendente';
const tomVoz = body.tom_voz || 'simp�tica e profissional';
const infoExtra = body.info_extra || '';

const planoSlug = body.plano || 'essencial';
const cupom = (body.cupom || '').toUpperCase().trim();
const origem = body.origem || 'site';

const profissionais = body.profissionais || [];
const servicos = body.servicos || [];

const precos = {
  essencial: { mensal: 297, adesao: 0, agendas: 1 },
  pro: { mensal: 497, adesao: 0, agendas: 5 },
  premium: { mensal: 897, adesao: 0, agendas: 10 }
};

const planoInfo = precos[planoSlug] || precos.essencial;

// Gerar tenant e instancia baseados no EMAIL (fixo) em vez de Date.now() (vari�vel)
const emailBase = email.toLowerCase().replace(/[^a-z0-9]/g, '-').substring(0, 30);
const nomeBase = nomeNegocio
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]/g, '-')
  .replace(/-+/g, '-')
  .replace(/^-+|-+$/g, '')
  .substring(0, 30);

// Instancia fixa por neg�cio - n�o muda entre execu��es
const instancia = nomeBase || emailBase;
const tenantId = instancia.replace(/-/g, '_');

let tipoAtivacao = 'trial';
let status = 'trial';
let trialEndDate = null;
let planoExpiraEm = null;
let adesaoPaga = false;

if (cupom === 'VALIDA3MESES') {
  tipoAtivacao = 'gratuito_3meses';
  status = 'ativo';
  const d = new Date(); d.setMonth(d.getMonth() + 3); planoExpiraEm = d.toISOString();
  adesaoPaga = true;
} else if (cupom === 'SOCIOVIP') {
  tipoAtivacao = 'gratuito_6meses';
  status = 'ativo';
  const d = new Date(); d.setMonth(d.getMonth() + 6); planoExpiraEm = d.toISOString();
  adesaoPaga = true;
} else {
  const d = new Date(); d.setDate(d.getDate() + 7); trialEndDate = d.toISOString();
}

const apikey = 'SUA_NOVA_API_KEY_AQUI';
const nomeNegocioCodificado = encodeURIComponent(nomeNegocio);
const linkConexao = `https://n8n.upviaagentes.com/webhook/conectar?i=${instancia}&k=${apikey}&n=${nomeNegocioCodificado}`;

return [{
  json: {
    tenant_id: tenantId,
    instancia: instancia,
    nome_completo: nomeCompleto,
    email: email,
    telefone: telefone,
    telefone_wpp: telefone + '@s.whatsapp.net',
    cpf_cnpj: cpfCnpj,
    nome_negocio: nomeNegocio,
    tipo_negocio: tipoNegocio,
    plano_slug: planoSlug,
    plano_nome: planoSlug.charAt(0).toUpperCase() + planoSlug.slice(1),
    preco_mensal: planoInfo.mensal,
    taxa_adesao: planoInfo.adesao,
    max_agentes: planoInfo.agendas,
    cupom: cupom,
    tipo_ativacao: tipoAtivacao,
    status: status,
    trial_end_date: trialEndDate,
    plano_expira_em: planoExpiraEm,
    adesso_paga: adesaoPaga,
    nome_atendente: nomeAtendente,
    tom_voz: tomVoz,
    endereco: endereco,
    instagram: instagram,
    horario_funcionamento: horarioFuncionamento,
    formas_pagamento: formasPagamento,
    info_extra: infoExtra,
    profissionais: profissionais,
    servicos: servicos,
    origem: origem,
    link_checkout_asaas: body.link_checkout_asaas || '',
    asaas_customer_id: body.asaas_customer_id || '',
    asaas_payment_id: body.asaas_payment_id || '',
    data_cadastro: new Date().toISOString(),
    link_conexao: linkConexao,
    cidade_estado:   cidadeEstado,
    cidade:          body.cidade || '',
    estado:          body.estado || '',
    whatsapp:        body.whatsapp || telefone,
    msg_boas_vindas: body.msg_boas_vindas || '',
    aceite_lgpd:     body.aceite_lgpd || false
  }
}];

const dados = $('Validar Cadastro').first().json;
const telefone = dados.telefone || '';
const telefoneFormatado = telefone.startsWith('55') ? telefone : '55' + telefone;

return [{
  json: {
    ...dados,
    telefone: telefoneFormatado,
    telefone_wpp: telefoneFormatado + '@s.whatsapp.net'
  }
}];

// Verificar se o Postgres retornou alguma inst�ncia existente
const result = $input.first().json;
const dados = $('Tratar Telefone (55)').first().json;

let jaExiste = false;

// Se o Postgres retornou um registro com instancia_whatsapp preenchida
if (result && result.instancia_whatsapp && result.instancia_whatsapp.trim() !== '') {
  jaExiste = true;
}

return [{
  json: {
    ...dados,
    instancia_ja_existe: jaExiste,
    instancia_existente: result ? result.instancia_whatsapp || '' : ''
  }
}];

