const body = $input.first().json.body || $input.first().json;
const event = body.event || '';
const payment = body.payment || body;

const eventosValidos = ['PAYMENT_CONFIRMED', 'PAYMENT_RECEIVED'];
if (!eventosValidos.includes(event)) {
  return [{ json: { ignorar: true, motivo: 'Evento ignorado: ' + event } }];
}

let metadata = {};
try {
  metadata = payment.externalReference
    ? JSON.parse(payment.externalReference)
    : {};
} catch(e) { metadata = {}; }

return [{
  json: {
    ignorar: false,
    asaas_customer_id: payment.customer || '',
    asaas_payment_id:  payment.id || '',
    valor_pago:        payment.value || 0,
    email:             metadata.email || payment.customerEmail || '',
    nome_negocio:      metadata.nome_negocio || '',
    tenant_id:         metadata.tenant_id || '',
    metadata:          metadata
  }
}];

const item = $input.first().json;

// Mapear plano para ID do produto no Asaas
const planoValores = {
  'essencial': { valor: 297, nome: 'AtendentIA Essencial' },
  'pro':       { valor: 497, nome: 'AtendentIA Pro' },
  'premium':   { valor: 897, nome: 'AtendentIA Premium' }
};

const plano = (item.plano || item.plano_slug || 'essencial').toLowerCase();
const info = planoValores[plano] || planoValores.essencial;

// Data de hoje = data do primeiro pagamento = data de vencimento mensal
const hoje = new Date();
const dueDate = hoje.toISOString().split('T')[0]; // YYYY-MM-DD

return [{
  json: {
    ...item,
    asaas_valor: info.valor,
    asaas_plano_nome: info.nome,
    asaas_due_date: dueDate,
    asaas_customer_name: item.nome_completo || item.nome_proprietario || '',
    asaas_customer_email: item.email || '',
    asaas_customer_phone: item.telefone || item.whatsapp || '',
    asaas_customer_cpf: item.cpf_cnpj || ''
  }
}];

const uuid = $('Registrar Cliente Admin').first().json.uuid;
const servicos = $('Tratar Telefone (55)').first().json.servicos || [];

return servicos
  .filter(s => s && s.nome && String(s.nome).trim() !== '')
  .map(s => {
    const precoNum = parseFloat(String(s.preco || '0').replace(/[^0-9,.-]/g, '').replace(',', '.')) || 0;
    const duracaoNum = parseInt(String(s.duracao || '60').replace(/[^0-9]/g, ''), 10) || 60;
    return {
      json: {
        id_estabelecimento: uuid,
        titulo_servico: String(s.nome).trim(),
        valor_base: precoNum,
        tempo_estimado_minutos: duracaoNum
      }
    };
  });

